(window.ARC_DATA = window.ARC_DATA || {}).arc = [{"id":"arc_matriarch","name":{"en":"Matriarch","zh":"族母"},"type":{"en":"Boss","zh":"首领"},"threat":"Extreme","desc":{"en":"The Matriarch is an imposing ARC machine that makes the Queen look friendly and can be found during a specific map condition.","zh":"族母是一台气势逼人的ARC机器，相比之下连女王都显得和善。只在特定的地图条件下出现。"},"weakness":{"en":"Central glowing core, which becomes exposed when it attacks. Leg joints are vulnerable too, as well as the red areas on the crown.","zh":"中央发光的核心，会在它攻击时暴露。腿部关节和头冠上的红色部位同样脆弱。"},"maps":["dam_battlegrounds"],"xp":{"destroy":1000,"loot":500},"drops":["arc_alloy","arc_circuitry","arc_performance_steel","advanced_arc_powercell","arc_flex_rubber","arc_synthetic_resin","magnetic_accelerator","matriarch_reactor"],"img":"assets/img/game/arc/arc_matriarch.jpg"},{"id":"arc_the_queen","name":{"en":"The Queen","zh":"女王"},"type":{"en":"Boss","zh":"首领"},"threat":"Extreme","desc":{"en":"A colossal machine deployed during Harvester Events. It's the Goliath of the ARC forces with incredible durability and lethal arsenal. Requires full squad coordination.","zh":"在「收割者」地图条件中出动的庞大机器，是ARC阵营里的巨无霸，极其耐打，火力致命。需要整个小队协同应对。"},"weakness":{"en":"The yellow joints on her legs. Exposes her core when firing the laser.","zh":"腿部的黄色关节。发射激光时会暴露核心。"},"maps":["dam_battlegrounds","the_spaceport","the_blue_gate"],"xp":{"destroy":1000,"loot":1000},"drops":["arc_alloy","advanced_arc_powercell","arc_motion_core","arc_circuitry","arc_coolant","arc_flex_rubber","arc_thermo_lining","arc_synthetic_resin","arc_performance_steel","advanced_mechanical_components","advanced_electrical_components","complex_gun_parts","magnetic_accelerator","queen_reactor"],"img":"assets/img/game/arc/arc_the_queen.jpg"},{"id":"arc_bastion","name":{"en":"Bastion","zh":"堡垒"},"type":{"en":"Heavy Assault","zh":"重型突击"},"threat":"Critical","desc":{"en":"Massive, crab-like machines that are slow but devastating. They're capable of shredding shields and dealing massive damage with heavy attacks.","zh":"形似螃蟹的庞大机器，行动迟缓但破坏力惊人。重击能撕碎护盾，造成巨额伤害。"},"weakness":{"en":"Destroy the canister on his rear, to expose it's weakpoint.","zh":"摧毁它背后的罐体，即可暴露弱点。"},"maps":["dam_battlegrounds","the_spaceport","the_blue_gate","buried_city","stella_montis"],"xp":{"destroy":500,"loot":250},"drops":["arc_alloy","arc_powercell","arc_motion_core","arc_circuitry","bastion_cell"],"img":"assets/img/game/arc/arc_bastion.jpg"},{"id":"arc_bombardier","name":{"en":"Bombardier","zh":"投弹手"},"type":{"en":"Heavy Artillery","zh":"重型炮击"},"threat":"Critical","desc":{"en":"A massive artillery unit designed for long-range bombardment. Equipped with devastating explosive capabilities and heavy armor, it can rain destruction from great distances.","zh":"专为远程轰炸设计的大型炮击单位。爆炸火力凶猛，装甲厚重，能从极远处倾泻毁灭性的打击。"},"weakness":{"en":"Shooting at the yellow rear canister deals direct damage to it's core.","zh":"射击后方的黄色罐体，可直接伤害它的核心。"},"maps":["dam_battlegrounds","the_spaceport","the_blue_gate","buried_city"],"xp":{"destroy":500,"loot":300},"drops":["arc_alloy","advanced_arc_powercell","bombardier_cell","launcher_ammo"],"img":"assets/img/game/arc/arc_bombardier.jpg"},{"id":"arc_leaper","name":{"en":"Leaper","zh":"跳跃者"},"type":{"en":"Siege Engine","zh":"攻城机器"},"threat":"Critical","desc":{"en":"Massive, arachnid-like siege engine with heavy armor and gravity-defying leap ability. Can clear impossible gaps and reach high vantage points.","zh":"形似蜘蛛的巨型攻城机器，装甲厚重，跳跃能力仿佛无视重力。能越过看似无法逾越的沟壑，跳上高处的制高点。"},"weakness":{"en":"Fire is most effective. Additionally you can shoot into it's eye.","zh":"火焰伤害最有效。也可以射击它的眼睛。"},"maps":["dam_battlegrounds","the_spaceport","the_blue_gate","buried_city"],"xp":{"destroy":500,"loot":500},"drops":["advanced_arc_powercell","arc_alloy","arc_circuitry","arc_flex_rubber","arc_motion_core","arc_performance_steel","arc_powercell","explosive_compound","leaper_pulse_unit","mechanical_components"],"img":"assets/img/game/arc/arc_leaper.jpg"},{"id":"arc_rocketeer","name":{"en":"Rocketeer","zh":"火箭手"},"type":{"en":"Flying Artillery","zh":"空中炮击"},"threat":"Critical","desc":{"en":"A formidable flying ARC that dominates airspace with powerful rocket attacks and devastating area-of-effect damage. Designed to saturate areas with explosions.","zh":"难缠的飞行ARC，凭借威力巨大的火箭和毁灭性的范围伤害称霸天空，专门用爆炸覆盖整片区域。"},"weakness":{"en":"Destroy two thrusters or shoot it's core, which is located underneath it.","zh":"摧毁两个推进器，或射击位于机身下方的核心。"},"maps":["dam_battlegrounds","the_spaceport","the_blue_gate","buried_city"],"xp":{"destroy":500,"loot":500},"drops":["arc_alloy","arc_powercell","arc_motion_core","arc_circuitry","advanced_arc_powercell","heavy_gun_parts","rocketeer_driver","heavy_ammo"],"img":"assets/img/game/arc/arc_rocketeer.jpg"},{"id":"arc_fireball","name":{"en":"Fireball","zh":"火球"},"type":{"en":"Area Denial","zh":"区域封锁"},"threat":"High","desc":{"en":"Small armored rolling ARC that spits flame. Opens front panel when near Raiders to burn them alive, exposing its soft core.","zh":"会喷火的小型装甲滚动ARC。靠近奇袭者时会打开前挡板喷火烧人，同时暴露脆弱的核心。"},"weakness":{"en":"Exposes it's core, when it's using the flamethrower.","zh":"喷火时会暴露核心。"},"maps":["dam_battlegrounds","the_spaceport","the_blue_gate","buried_city","stella_montis"],"xp":{"destroy":100,"loot":100},"drops":["arc_alloy","arc_powercell","fireball_burner"],"img":"assets/img/game/arc/arc_fireball.jpg"},{"id":"arc_hornet","name":{"en":"Hornet","zh":"马蜂"},"type":{"en":"Medium Drone","zh":"中型无人机"},"threat":"High","desc":{"en":"Medium-class drone with armored rotors. It fires focused, high-speed projectiles with a brief red laser warning. Designed to shred shields and light armor.","zh":"旋翼带装甲的中型无人机。开火前会短暂亮起红色激光预警，随后射出集中的高速弹丸，专门用来撕碎护盾和轻型装甲。"},"weakness":{"en":"Unarmored rear thrusters.","zh":"后部没有装甲的推进器。"},"maps":["dam_battlegrounds","the_spaceport","the_blue_gate","buried_city"],"xp":{"destroy":150,"loot":250},"drops":["arc_alloy","arc_powercell","hornet_driver","simple_gun_parts","medium_ammo"],"img":"assets/img/game/arc/arc_hornet.jpg"},{"id":"arc_sentinel","name":{"en":"Sentinel","zh":"哨卫"},"type":{"en":"Sniper Turret","zh":"狙击炮塔"},"threat":"High","desc":{"en":"Stationary but deadly turrets that perch on high vantage points. They scan for targets with long-range precision and lock onto players from a distance.","zh":"固定不动却十分致命的炮塔，盘踞在高处的制高点。它们能远距离精确扫描目标，从远处锁定玩家。"},"weakness":{"en":"The yellow unarmored canister will be your main target.","zh":"主要目标是没有装甲的黄色罐体。"},"maps":["dam_battlegrounds","the_spaceport","the_blue_gate","buried_city"],"xp":{"destroy":200,"loot":300},"drops":["arc_alloy","arc_powercell","arc_coolant","arc_synthetic_resin","arc_thermo_lining","arc_motion_core","sentinel_firing_core","heavy_ammo"],"img":"assets/img/game/arc/arc_sentinel.jpg"},{"id":"arc_shredder","name":{"en":"Shredder","zh":"粉碎者"},"type":{"en":"Area Denial","zh":"区域封锁"},"threat":"High","desc":{"en":"The Shredder appears in Stella Montis, challenging Raiders to stay sharp in close-quarter encounters.","zh":"粉碎者出没于星辰山，在近距离遭遇战中考验奇袭者的反应。"},"weakness":{"en":"Primary weakness is the 'eye-bar' at it's head. You may see the orange core between it's armour plates, which you can shoot too.","zh":"主要弱点是头部的“眼条”。装甲板之间露出的橙色核心也可以射击。"},"maps":["stella_montis"],"xp":{"destroy":200,"loot":250},"drops":["arc_alloy","arc_powercell","shredder_gyro","shotgun_ammo"],"img":"assets/img/game/arc/arc_shredder.jpg"},{"id":"arc_spotter","name":{"en":"Spotter","zh":"侦察员"},"type":{"en":"Scout Drone","zh":"侦察无人机"},"threat":"High","desc":{"en":"Spotters are flying support drones for the Bombardier. They will point a laser at any Raider in line-of-sight so the Bombardier can accurately target them. If both Spotters are destroyed a new pair will respawn. When the Bombardier is destroyed the Spotters will fly away.","zh":"侦察员是为投弹手提供支援的飞行无人机。它们会用激光照射视线内的奇袭者，让投弹手精确瞄准。两架侦察员都被摧毁后，会再出现新的一对；投弹手被摧毁后，侦察员会飞走。"},"weakness":{"en":"Unarmored thrusters","zh":"没有装甲的推进器。"},"maps":["dam_battlegrounds","the_spaceport","the_blue_gate","buried_city"],"xp":{"destroy":100,"loot":200},"drops":["spotter_relay","arc_alloy","arc_powercell","sensors"],"img":"assets/img/game/arc/arc_spotter.jpg"},{"id":"arc_pop","name":{"en":"Pop","zh":"爆爆"},"type":{"en":"Explosive","zh":"自爆"},"threat":"Moderate","desc":{"en":"Small explosive ARC that detonates when approached. Quick elimination required to prevent area damage.","zh":"靠近就会引爆的小型自爆ARC。必须尽快消灭，以免受到范围伤害。"},"weakness":{"en":"Just shoot it.","zh":"直接射击即可。"},"maps":["dam_battlegrounds","the_spaceport","the_blue_gate","buried_city","stella_montis"],"xp":{"destroy":50,"loot":100},"drops":["arc_alloy","arc_powercell","arc_thermo_lining","crude_explosives","pop_trigger"],"img":"assets/img/game/arc/arc_pop.jpg"},{"id":"arc_snitch","name":{"en":"Snitch","zh":"告密者"},"type":{"en":"Scout Drone","zh":"侦察无人机"},"threat":"Moderate","desc":{"en":"A swift, unarmored scout drone with three rotors. While fragile, it acts as an aerial alarm system, calling in reinforcements when it spots Raiders.","zh":"迅捷、无装甲的三旋翼侦察无人机。虽然脆弱，却是空中的警报器，一旦发现奇袭者就会呼叫增援。"},"weakness":{"en":"Thrusters or the underside plating.","zh":"推进器或底部装甲板。"},"maps":["dam_battlegrounds","the_spaceport","the_blue_gate","buried_city"],"xp":{"destroy":100,"loot":200},"drops":["arc_alloy","arc_powercell","arc_synthetic_resin","sensors","snitch_scanner"],"img":"assets/img/game/arc/arc_snitch.jpg"},{"id":"arc_tick","name":{"en":"Tick","zh":"跳蚤"},"type":{"en":"Ambush Predator","zh":"伏击"},"threat":"Moderate","desc":{"en":"Small, spider-like robots that leap onto players, attaching themselves to your head. They're fast and disorienting, designed to punish careless Raiders.","zh":"形似蜘蛛的小型机器人，会扑到玩家身上，吸附在头部。行动迅速，让人晕头转向，专门惩罚粗心大意的奇袭者。"},"weakness":{"en":"Just shoot it. It's also one-hit with your melee weapon.","zh":"直接射击即可，近战也能一击摧毁。"},"maps":["dam_battlegrounds","the_spaceport","the_blue_gate","buried_city","stella_montis"],"xp":{"destroy":50,"loot":100},"drops":["arc_alloy","tick_pod"],"img":"assets/img/game/arc/arc_tick.jpg"},{"id":"arc_turret","name":{"en":"Turret","zh":"炮塔"},"type":{"en":"Defense System","zh":"防御系统"},"threat":"Moderate","desc":{"en":"Small, unarmored turret providing close-quarters defense. Mounted on interior walls, it scans for movement and unleashes rapid fire when it spots Raiders.","zh":"负责近距离防御的小型无装甲炮塔。安装在室内墙上，会扫描移动目标，发现奇袭者就猛烈开火。"},"weakness":{"en":"Unarmored. Shooting it is enough.","zh":"没有装甲，直接射击即可。"},"maps":["dam_battlegrounds","the_spaceport","the_blue_gate","buried_city","stella_montis"],"xp":{"destroy":100,"loot":200},"drops":["arc_alloy","light_ammo","simple_gun_parts"],"img":"assets/img/game/arc/arc_turret.jpg"},{"id":"arc_wasp","name":{"en":"Wasp","zh":"黄蜂"},"type":{"en":"Flying Drone","zh":"飞行无人机"},"threat":"Moderate","desc":{"en":"Flying, drone-like robots equipped with powerful machine guns. They operate in swarms, are fast, agile, and relentless. Their buzzing and screeching audio cues are your first warning.","zh":"配备强力机枪的飞行无人机。它们成群出动，速度快、身手灵活、穷追不舍。嗡嗡声和尖啸声就是它们来袭的第一个信号。"},"weakness":{"en":"Unarmored thrusters."},"maps":["dam_battlegrounds","the_spaceport","the_blue_gate","buried_city"],"xp":{"destroy":100,"loot":200},"drops":["arc_alloy","arc_powercell","wasp_driver","light_ammo"],"img":"assets/img/game/arc/arc_wasp.jpg"},{"id":"arc_surveyor","name":{"en":"Surveyor","zh":"ARC勘测师"},"type":{"en":"Reconnaissance","zh":"侦察"},"threat":"Low","desc":{"en":"The largest of the rolling ARC. It stops periodically to transmit signals. Rarely attacks, usually runs away from Raiders. Breaks into many pieces as damage is taken.","zh":"滚动型ARC中体型最大的一种。会不时停下来发送信号，很少主动攻击，通常会躲开奇袭者。受到伤害时会碎裂成许多块。"},"weakness":{"en":"Exposes his energy core when shooting his blue beam into the sky.","zh":"向天空发射蓝色光束时会暴露能量核心。"},"maps":["dam_battlegrounds","the_spaceport","the_blue_gate","buried_city"],"xp":{"destroy":200,"loot":300},"drops":["arc_alloy","arc_powercell","arc_motion_core","arc_circuitry","surveyor_vault"],"img":"assets/img/game/arc/arc_surveyor.jpg"}];
